"""Date-window membership for the date_window fixture."""

from __future__ import annotations

import datetime


def _parse_date(date_str: str) -> datetime.date:
    """Parse a strict ISO date string, raising ValueError if malformed."""
    if not isinstance(date_str, str):
        raise ValueError(f"Expected string, got {type(date_str)}")
    # Check format strictly: must be exactly YYYY-MM-DD
    if len(date_str) != 10 or date_str[4] != '-' or date_str[7] != '-':
        raise ValueError(f"Malformed date: {date_str!r}")
    # Ensure all parts are numeric and zero-padded (no leading spaces, etc.)
    year_s, month_s, day_s = date_str[:4], date_str[5:7], date_str[8:10]
    if not (year_s.isdigit() and month_s.isdigit() and day_s.isdigit()):
        raise ValueError(f"Malformed date: {date_str!r}")
    # Verify zero-padding by checking the string matches what we'd produce
    year, month, day = int(year_s), int(month_s), int(day_s)
    try:
        d = datetime.date(year, month, day)
    except ValueError:
        raise ValueError(f"Invalid calendar date: {date_str!r}")
    # Check that the formatted date matches the input exactly (ensures zero-padding)
    if d.strftime("%Y-%m-%d") != date_str:
        raise ValueError(f"Malformed date (not zero-padded): {date_str!r}")
    return d


def in_any_window(target_date: str, windows: list[tuple[str, str]]) -> bool:
    """Return whether target_date falls inside any date window."""
    # Parse and validate target date first
    target = _parse_date(target_date)

    # Parse and validate all windows before checking membership
    parsed_windows = []
    for start, end in windows:
        s = _parse_date(start)
        e = _parse_date(end)
        if s > e:
            raise ValueError(
                f"Window start {start!r} is after end {end!r}"
            )
        parsed_windows.append((s, e))

    # Check membership
    for s, e in parsed_windows:
        if s <= target <= e:
            return True
    return False
